 private function lockIntegrity(int $id,string $reason):void{Db::name('users')->where('id',$id)->update(['integrity_locked'=>1,'integrity_reason'=>mb_substr($reason,0,500),'integrity_locked_at'=>date('Y-m-d H:i:s'),'status'=>0,'key_status'=>0,'updated_at'=>date('Y-m-d H:i:s')]);}

 private function done($response,?array $lease){ConcurrencyLimiter::release($lease);if($this->timingStart>0){$total=(microtime(true)-$this->timingStart)*1000;$response->header(['Server-Timing'=>'gateway_total;dur='.round($total,2).', billing_log;dur='.round($this->finishMs,2)]);}return $response;}
 private function err($msg,$type,$status,$rid=''){ $x=['error'=>['message'=>$msg,'type'=>$type]];if($rid)$x['request_id']=$rid;return json($x,$status);}
