 private function collectDefinedParams(array $defs){$params=[];$raw=file_get_contents('php://input');$json=json_decode($raw,true);if(!is_array($json))$json=[];$query=request()->get();$pathParams=request()->param();foreach($defs as $d){$loc=$d['location'];$name=$d['name'];$exists=false;$v=null;if($loc==='query'){$exists=array_key_exists($name,$query);$v=$exists?$query[$name]:null;}elseif($loc==='header'){$v=request()->header($name,null);$exists=$v!==null;}elseif($loc==='body'){$exists=array_key_exists($name,$json);$v=$exists?$json[$name]:input('post.'.$name,null);$exists=$exists||$v!==null;}elseif($loc==='path'){$exists=array_key_exists($name,$pathParams);$v=$exists?$pathParams[$name]:null;}if(!$exists&&$d['default_value']!==null){$v=$d['default_value'];$exists=true;}if(!$exists){if($d['required'])return[null,'缺少必填参数：'.$name];continue;}$ok=false;$v=$this->cast($v,$d['data_type'],$ok);if(!$ok)return[null,'参数类型不正确：'.$name];$params[$name]=$v;}return[$params,null];}
