 private function buildDefined(array $ep,array $defs){$url=(string)$ep['target_url'];$headers=['Accept: application/json'];$query=[];$bodyData=[];$raw=file_get_contents('php://input');$json=json_decode($raw,true);if(!is_array($json))$json=[];$inputQuery=request()->get();$pathParams=request()->param();foreach($defs as $d){$loc=$d['location'];$name=$d['name'];$exists=false;$v=null;if($loc==='query'){$exists=array_key_exists($name,$inputQuery);$v=$exists?$inputQuery[$name]:null;}elseif($loc==='header'){$v=request()->header($name,null);$exists=$v!==null;}elseif($loc==='body'){$exists=array_key_exists($name,$json);$v=$exists?$json[$name]:input('post.'.$name,null);$exists=$exists||$v!==null;}elseif($loc==='path'){$exists=array_key_exists($name,$pathParams);$v=$exists?$pathParams[$name]:null;}if(!$exists&&$d['default_value']!==null){$v=$d['default_value'];$exists=true;}if(!$exists){if($d['required'])return[null,'Missing required parameter: '.$name];continue;}$ok=false;$v=$this->cast($v,$d['data_type'],$ok);if(!$ok)return[null,'Invalid parameter type: '.$name];if($loc==='query')$query[$name]=$v;elseif($loc==='header')$headers[]=$name.': '.(is_scalar($v)?$v:json_encode($v,JSON_UNESCAPED_UNICODE));elseif($loc==='body')$bodyData[$name]=$v;elseif($loc==='path')$url=str_replace('{'.$name.'}',rawurlencode((string)$v),$url);}if($query)$url.=(str_contains($url,'?')?'&':'?').http_build_query($query,'','&',PHP_QUERY_RFC3986);$body='';if($bodyData){$body=json_encode($bodyData,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$headers[]='Content-Type: application/json';}return[['url'=>$url,'headers'=>$headers,'body'=>$body],null];}
 private function applyUpstreamAuth(array $ep,array $req):array{
  $type=(string)($ep['upstream_auth_type']??'none');$secret=(string)($ep['upstream_auth_secret']??'');if($secret!=='')$secret=SecretStore::decrypt($secret);$name=trim((string)($ep['upstream_auth_name']??''));
