  elseif($type==='header'&&$secret!==''&&$name!=='')$req['headers'][]=$name.': '.$secret;
  elseif($type==='query'&&$secret!==''&&$name!=='')$req['url'].=(str_contains($req['url'],'?')?'&':'?').rawurlencode($name).'='.rawurlencode($secret);
  elseif($type==='basic'&&$secret!=='')$req['headers'][]='Authorization: Basic '.base64_encode($name.':'.$secret);
