 public function chatCompletions(){return $this->handle('chat-completions');}
 private function authorBatchCost(array $params,array $result,bool $success,int $defaultCost):int{if(!$success)return$defaultCost;$count=max(0,(int)($result['billing']['post_count']??0));if($count===0)return 0;$perPostSite=$this->isPerPostAuthorSite((string)($params['url']??''));if($perPostSite)return(int)ceil($count/3);$pages=max(0,(int)($result['billing']['page_count']??1));return$pages*$defaultCost;}
