 private function isSuccess(array $ep,int $status,$json):bool{$mode=$ep['success_mode']??'http_2xx';if($mode==='http_2xx')return$status>=200&&$status<300;if($mode==='json_field'){if($status<200||$status>=300||!is_array($json))return false;$v=$json;foreach(explode('.',(string)$ep['success_json_field']) as $part){if($part===''||!is_array($v)||!array_key_exists($part,$v))return false;$v=$v[$part];}return(string)$v===(string)$ep['success_json_value'];}return false;}
